(function(){'use strict';const G=window.N2Grammar,$=id=>document.getElementById(id),escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let library,view='daily',marks={};const now=new Date(),today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-'),key='n2-grammar-review-v1';try{marks=JSON.parse(localStorage.getItem(key)||'{}');if(!marks||Array.isArray(marks)||typeof marks!=='object')marks={}}catch{marks={}}
const evidenceLabels={exam_observed:'试卷用法已核对',curriculum_core:'课程重点 · 非频率排名',foundation:'基础衔接 · 非 N2 专属'};
function safeUrl(url){try{const u=new URL(url);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function sourceLink(s){const url=safeUrl(s.url);return url?`<a href="${escape(url)}" target="_blank" rel="noopener noreferrer">${escape(s.title||s.id)} ↗</a>`:escape(s.title||s.id||'来源未提供链接')}
function markId(id){return today+':'+id}
function attempts(){return window.getN2Attempts?.()||[]}
function render(){if(!library)return;const daily=G.daily(library.cards,attempts(),today),q=$('grammarSearch').value.trim().toLowerCase(),category=$('grammarCategory').value,evidence=$('grammarEvidence').value;let cards=(view==='daily'?daily:library.cards).filter(c=>(category==='all'||c.category===category)&&(evidence==='all'||c.evidence_type===evidence)&&(!q||[c.pattern,c.connection,c.meaning_zh,c.category,c.contrast_trap].join(' ').toLowerCase().includes(q)));$('dailyReviewed').textContent=daily.filter(c=>marks[markId(c.id)]===true).length+' / '+daily.length;$('grammarCount').textContent=`${today} · ${view==='daily'?'今日队列':'全部语法'} · 当前 ${cards.length} 张 / 总计 ${library.cards.length} 张 · 打卡日期使用此设备本地日期`;$('grammarCards').innerHTML=cards.length?cards.map(c=>{const weight=G.score(c,attempts()),checked=marks[markId(c.id)]===true;const sources=[...c.exam_sources,...(c.reference_source_ids||[])].map(ref=>{if(typeof ref==='string')return library.sources.find(s=>s.id===ref);const source=library.sources.find(s=>s.id===ref.source_id)||ref;return {...source,title:(source.title||ref.source_id||'来源')+(ref.question?' · Q'+ref.question:'')+(ref.pdf_page?' · PDF第'+ref.pdf_page+'页':'')}}).filter(Boolean);return `<article class="grammar-card panel"><div class="grammar-card-top"><span class="chip">${escape(c.category)}</span><span>${escape(c.level_label)}</span></div><h3 lang="ja">${escape(c.pattern)}</h3><div class="grammar-evidence">${escape(evidenceLabels[c.evidence_type])}${weight?`<span>关联历史错因 ${weight} 次</span>`:''}</div><details><summary>回想后展开 · 接续 / 含义 / 例句</summary><dl><dt>接续</dt><dd lang="ja">${escape(c.connection)}</dd><dt>含义</dt><dd>${escape(c.meaning_zh)}</dd></dl><blockquote><p lang="ja">${escape(c.example_ja)}</p><small>${escape(c.translation_zh)}</small></blockquote>${c.readings.length?`<p class="reading-hints">读音：${c.readings.map(r=>escape(r.word)+'（'+escape(r.reading)+'）').join(' · ')}</p>`:''}<div class="contrast"><strong>别混淆</strong><p>${escape(c.contrast_trap)}</p></div>${sources.length?'<div class="card-sources">依据：'+sources.map(sourceLink).join(' · ')+'</div>':'<p class="muted">课程整理项；不声称有逐题频率证据。</p>'}</details><label class="review-mark"><input type="checkbox" data-card="${escape(c.id)}" ${checked?'checked':''}><span>${checked?'今天已复习':'记为今日复习'}</span><small>仅打卡</small></label></article>`}).join(''):'<div class="empty panel">当前筛选没有语法卡片。试试全部语法或清除分类。</div>';document.querySelectorAll('[data-card]').forEach(input=>input.addEventListener('change',()=>{const next={...marks,[markId(input.dataset.card)]:input.checked};try{localStorage.setItem(key,JSON.stringify(next));marks=next;input.parentElement.querySelector('span').textContent=input.checked?'今天已复习':'记为今日复习';$('dailyReviewed').textContent=daily.filter(c=>marks[markId(c.id)]===true).length+' / '+daily.length}catch{input.checked=!input.checked;$('grammarCount').textContent='浏览器无法保存打卡；未修改成绩或学习记录。请检查存储权限。'}}))}
function setView(next){view=next;$('dailyCards').classList.toggle('active',view==='daily');$('allCards').classList.toggle('active',view==='all');render()}
$('dailyCards').onclick=()=>setView('daily');$('allCards').onclick=()=>setView('all');$('grammarSearch').oninput=render;$('grammarCategory').onchange=render;$('grammarEvidence').onchange=render;window.addEventListener('n2-records-ready',render);
fetch('grammar-cards.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('资料暂不可用');return r.json()}).then(d=>{library=G.validate(d);$('grammarCategory').innerHTML='<option value="all">全部分类</option>'+[...new Set(d.cards.map(c=>c.category))].sort().map(c=>`<option value="${escape(c)}">${escape(c)}</option>`).join('');$('grammarSources').innerHTML=d.sources.map(s=>'<p>'+sourceLink(s)+(s.scope?'<br><small>'+escape(s.scope)+'</small>':'')+'</p>').join('');if(typeof d.source_policy==='string')$('grammarSourcePolicy').textContent=d.source_policy;render()}).catch(e=>{$('grammarCount').textContent='语法资料读取失败：'+e.message+'；作答数据与准确率不受影响。'});
})();
